# Display name -> file stem. The stem names both the preset folder and the
# `<stem>_key_bindings.txt` CS2 writes to, so it cannot be derived from the
# display name (assetbrowser, propertyeditor, subrecteditor, helpsystem are
# single words while modeldoc_editor and friends are not).
EDITOR_STEMS = {
    'Hammer': 'hammer',
    'ModelDoc Editor': 'modeldoc_editor',
    'AnimGraph Editor': 'animgraph_editor',
    'Particle Editor': 'pet',
    'Post Process Editor': 'postprocess_editor',
    'Subrect Editor': 'subrecteditor',
    'Asset Browser': 'assetbrowser',
    'Property Editor': 'propertyeditor',
    'Workshop Manager': 'workshop_manager',
    'Shared Tool': 'shared_tool',
    'Help System': 'helpsystem',
    'Global': 'global',
}

EDITOR_CATALOGS['hammer'] = hammer_commands
EDITOR_DEFAULTS['hammer'] = hammer_default
EDITOR_MACROS['hammer'] = hammer_macros

# Anything Valve binds by default is something the user may want to rebind, so
# keep every catalog a superset of its defaults instead of curating both lists.
for _stem, _default in EDITOR_DEFAULTS.items():
    for _binding in _default['m_Bindings']:
        _commands = EDITOR_CATALOGS.setdefault(_stem, {}).setdefault(_binding['m_Context'], [])
        if _binding['m_Command'] not in _commands:
            _commands.append(_binding['m_Command'])
